plot3([0, T], [0, 0], [0, 0], 'k--', 'LineWidth', 1.5, ... %[output:12573e38]
    'DisplayName', '目标状态 (x=0)'); %[output:12573e38]

% 绘制开环系统响应（无控制）
x_open_sampled = x_open(1:skip:end);
plot3(t_sampled, x_open_sampled, zeros(size(t_sampled)), 'm--', 'LineWidth', 1.5, ... %[output:12573e38]
