fprintf('策略2 (较强反馈, K=%.4f): 总代价 = %.4f\n', K_strong, total_cost_strong); %[output:4c08c1a9]
fprintf('策略3 (保守控制, K=%.4f): 总代价 = %.4f\n', K_con, total_cost_con); %[output:9aadf2fb]
fprintf('开环系统 (无控制): 总代价 = %.4f\n\n', total_cost_open); %[output:5b35b5b6]

fprintf('闭环系统极点分析:\n'); %[output:9a48e17a]
fprintf('策略1 (LQR最优): 闭环极点 λ = %.4f, 收敛速率 = %.4f\n', p_opt, -p_opt); %[output:7fe5cffb]
fprintf('策略2 (较强反馈): 闭环极点 λ = %.4f, 收敛速率 = %.4f\n', p_strong, -p_strong); %[output:8a654a34]
fprintf('策略3 (保守控制): 闭环极点 λ = %.4f, 收敛速率 = %.4f\n', p_con, -p_con); %[output:82f0cf4c]
fprintf('开环系统: 开环极点 λ = %.4f, 收敛速率 = %.4f\n\n', p_open, -p_open); %[output:00fe34b5]

fprintf('最优性分析:\n'); %[output:9285bb3f]
fprintf('LQR最优策略的总代价最小，比策略2低 %.2f%%\n', (total_cost_strong-total_cost_opt)/total_cost_strong*100); %[output:9cb3faca]
fprintf('LQR最优策略的总代价最小，比策略3低 %.2f%%\n', (total_cost_con-total_cost_opt)/total_cost_con*100); %[output:3bdceb86]
fprintf('LQR最优策略的总代价最小，比开环系统低 %.2f%%\n\n', (total_cost_open-total_cost_opt)/total_cost_open*100); %[output:3b6ea109]

fprintf('控制效果分析:\n'); %[output:5aebb801]
fprintf('策略1 (LQR最优): 控制力度适中，收敛平滑，代价最小\n'); %[output:9679846c]
fprintf('策略2 (较强反馈): 控制力度较大，收敛较快，但控制能量消耗较多\n'); %[output:04e9c434]
fprintf('策略3 (保守控制): 控制力度很小，收敛缓慢，状态误差持续存在时间长\n'); %[output:6e632e5d]
fprintf('开环系统: 无控制，收敛最慢，代价最大\n'); %[output:4d06f647]

%% 12. 验证解析解与数值解的一致性
figure('Color', 'w', 'Position', [400, 200, 800, 400]); %[output:5766a6f8]
subplot(1,2,1); %[output:5766a6f8]
hold on; grid on; box on; %[output:5766a6f8]
plot(t_analytic, x_opt_analytic, 'b-', 'LineWidth', 2, 'DisplayName', '解析解'); %[output:5766a6f8]
plot(t, x_opt, 'r--', 'LineWidth', 1.5, 'DisplayName', '数值解'); %[output:5766a6f8]
xlabel('时间 t (秒)', 'FontSize', 11, 'FontWeight', 'bold'); %[output:5766a6f8]
ylabel('系统状态 x(t)', 'FontSize', 11, 'FontWeight', 'bold'); %[output:5766a6f8]
title('LQR最优控制: 解析解与数值解对比', 'FontSize', 12, 'FontWeight', 'bold'); %[output:5766a6f8]
legend('Location', 'best'); %[output:5766a6f8]

% 计算相对误差
rel_error = abs(x_opt(1:10:end) - interp1(t_analytic, x_opt_analytic, t(1:10:end))) ./ ...
    abs(interp1(t_analytic, x_opt_analytic, t(1:10:end)));
max_rel_error = max(rel_error);

subplot(1,2,2); %[output:5766a6f8]
plot(t(1:10:end), rel_error, 'k-', 'LineWidth', 1.5); %[output:5766a6f8]
grid on; box on; %[output:5766a6f8]
xlabel('时间 t (秒)', 'FontSize', 11, 'FontWeight', 'bold'); %[output:5766a6f8]
ylabel('相对误差', 'FontSize', 11, 'FontWeight', 'bold'); %[output:5766a6f8]
title(sprintf('相对误差 (最大: %.2e)', max_rel_error), 'FontSize', 12, 'FontWeight', 'bold'); %[output:5766a6f8]

